import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"; import { useState } from "react"; import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native"; import { ModuleCard } from "../../ui/ModuleCard"; import { Screen } from "../../ui/Screen"; import { colors, radius, spacing } from "../../ui/tokens"; import { firebaseAuth } from "../auth/firebase"; import { getCategories } from "../catalog/catalog.api"; import { createVendorCategoryRequest, getVendorCategoryRequests } from "./vendor.api";
export function VendorCategoryRequestsScreen() { const user = firebaseAuth?.currentUser ?? null; const cache = useQueryClient(); const categories = useQuery({ queryKey: ["catalog", "categories"], queryFn: getCategories }); const requests = useQuery({ queryKey: ["vendor", "category-requests"], queryFn: () => getVendorCategoryRequests(user!), enabled: Boolean(user) }); const [categoryId, setCategoryId] = useState(""); const [reason, setReason] = useState(""); const create = useMutation({ mutationFn: () => createVendorCategoryRequest(user!, { categoryId, reason }), onSuccess: async () => { setReason(""); await cache.invalidateQueries({ queryKey: ["vendor", "category-requests"] }); } }); return <Screen eyebrow="SELLER ACCESS" title="Category requests" description="Request approval to sell within an existing marketplace category."><ModuleCard title="New request" meta="Select a category and explain the product assortment you plan to list."><View style={styles.chips}>{categories.data?.map((category) => <Pressable key={category.id} onPress={() => setCategoryId(category.id)} style={[styles.chip, categoryId === category.id && styles.active]}><Text style={[styles.chipText, categoryId === category.id && styles.activeText]}>{category.name}</Text></Pressable>)}</View><TextInput multiline onChangeText={setReason} placeholder="Why does your shop need this category?" placeholderTextColor={colors.muted} style={styles.input} value={reason} />{create.error ? <Text style={styles.error}>{create.error.message}</Text> : null}<Pressable disabled={!categoryId || reason.trim().length < 5 || create.isPending} onPress={() => create.mutate()} style={styles.primary}><Text style={styles.primaryText}>{create.isPending ? "Submitting…" : "Submit request"}</Text></Pressable></ModuleCard>{requests.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{requests.data?.map((request) => <ModuleCard key={request.id} title={request.categoryPath} meta={`${request.status.toUpperCase()} · ${new Date(request.createdAt).toLocaleDateString()}`}><Text style={styles.body}>{request.reason}</Text>{request.reviewReason ? <Text style={styles.muted}>Admin: {request.reviewReason}</Text> : null}</ModuleCard>)}</Screen>; }
const styles = StyleSheet.create({ chips: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, chip: { borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, paddingHorizontal: spacing.md, paddingVertical: spacing.sm }, active: { backgroundColor: colors.primarySoft, borderColor: colors.primary }, chipText: { color: colors.muted, fontWeight: "700" }, activeText: { color: colors.primary }, input: { borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 100, padding: spacing.md, textAlignVertical: "top" }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, minHeight: 46, justifyContent: "center" }, primaryText: { color: "#fff", fontWeight: "900" }, body: { color: colors.text }, muted: { color: colors.muted }, error: { color: colors.danger } });
